DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.evaluation_save_activity(text,jsonb,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,',p_activity->>''state'',',',''Draft'','); definition:=replace(definition,'state=EXCLUDED.state','state=''Draft'''); definition:=replace(definition,'INSERT INTO public."Evaluation_Changes"','UPDATE public."Evaluation_Activities" SET state=p_activity->>''state'' WHERE id=aid; INSERT INTO public."Evaluation_Changes"'); EXECUTE definition; END $$;